// Re-apply the observed-series join to the COMMITTED snapshot, offline (PR133).
//
// Use when a committed snapshot was generated by a sync whose join missed the
// newest sample (or by the pre-PR133 exact-date join, which leaked synthetic
// placeholders — the 25 Jul 2026 realised-price defect). Rebuilds the cycle-5
// joined metrics and todayProvenance purely from the onchain series already
// inside the snapshot file — no network — and rewrites src/lib/data/snapshot.ts.
//
// Run: npm run repair-snapshot-join

import { writeFile } from "node:fs/promises";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { SNAPSHOT } from "../src/lib/data/snapshot";
import type { Snapshot } from "../src/lib/data/types";
import { joinObservedSeries } from "../src/lib/data/observedJoin";

const SNAPSHOT_PATH = resolve(
  dirname(fileURLToPath(import.meta.url)),
  "../src/lib/data/snapshot.ts",
);

const BG = "BGeometrics · bitcoin-data.com (current cycle)";
const JOINS: Array<[string, "mvrvZ" | "nupl" | "sopr" | "realizedPrice" | "reserveRisk" | "rhodl"]> = [
  ["mvrvZscore", "mvrvZ"],
  ["nupl", "nupl"],
  ["sopr", "sopr"],
  ["realizedPrice", "realizedPrice"],
  ["reserveRisk", "reserveRisk"],
  ["rhodl", "rhodl"],
];

function serialise(snapshot: Snapshot): string {
  const json = JSON.stringify(snapshot, (_k, v) =>
    typeof v === "number" && Number.isFinite(v) ? Number(v.toFixed(6)) : v,
  );
  return `// AUTO-GENERATED by \`npm run sync\` — do not edit by hand.
// Regenerate with: npm run sync
import type { Snapshot } from "./types";

export const SNAPSHOT: Snapshot = ${json};
`;
}

async function main() {
  const snapshot: Snapshot = JSON.parse(JSON.stringify(SNAPSHOT));
  const cycle5 = snapshot.cycles.find((c) => c.id === 5);
  const series = snapshot.onchain?.series;
  if (!cycle5 || !series) {
    console.log("No cycle 5 or no onchain series in the committed snapshot — nothing to repair.");
    return;
  }
  const base = Date.parse(cycle5.halvingDate);
  const newest = cycle5.samples[cycle5.samples.length - 1];
  const before = { ...newest };
  const todayProvenance: NonNullable<Snapshot["todayProvenance"]> = {};
  for (const [seriesKey, sampleKey] of JOINS) {
    const result = joinObservedSeries({
      samples: cycle5.samples as unknown as Array<{ day: number } & Record<string, unknown>>,
      sampleKey,
      series: series[seriesKey] ?? [],
      halvingDateMs: base,
      sourceLabel: BG,
      modelledLabel: "modelled — feed unavailable",
    });
    todayProvenance[sampleKey] = result.newestProvenance;
  }
  snapshot.todayProvenance = Object.keys(todayProvenance).length ? todayProvenance : null;

  await writeFile(SNAPSHOT_PATH, serialise(snapshot), "utf8");
  console.log(`✓ Repaired ${SNAPSHOT_PATH}`);
  for (const [, sampleKey] of JOINS) {
    const b = (before as unknown as Record<string, number>)[sampleKey];
    const a = (newest as unknown as Record<string, number>)[sampleKey];
    const p = todayProvenance[sampleKey];
    const changed = b !== a ? `  ${b} -> ${a}` : "  (unchanged)";
    console.log(`  ${sampleKey}: ${p?.mode}${p?.observedAt ? ` obs ${p.observedAt} (${p.ageDays}d)` : ""}${changed}`);
  }
}

main().catch((e) => {
  console.error("Repair failed:", e);
  process.exit(1);
});
